package br.com.marquesautodetail.api.auth;
import br.com.marquesautodetail.api.auth.dto.*;import br.com.marquesautodetail.api.empresa.*;import br.com.marquesautodetail.api.endereco.Endereco;import br.com.marquesautodetail.api.security.JwtService;import br.com.marquesautodetail.api.usuario.*;import org.springframework.security.authentication.*;import org.springframework.security.crypto.password.PasswordEncoder;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
@Service public class AuthService{ private final UsuarioRepository usuarios; private final EmpresaRepository empresas; private final PasswordEncoder encoder; private final JwtService jwt; private final AuthenticationManager authManager; public AuthService(UsuarioRepository usuarios,EmpresaRepository empresas,PasswordEncoder encoder,JwtService jwt,AuthenticationManager authManager){this.usuarios=usuarios;this.empresas=empresas;this.encoder=encoder;this.jwt=jwt;this.authManager=authManager;}
 @Transactional public AuthResponse cadastrarCliente(RegisterRequest r){return cadastrar(r,Role.CLIENTE);} @Transactional public AuthResponse cadastrarEmpresa(RegisterRequest r){return cadastrar(r,Role.EMPRESA);} private AuthResponse cadastrar(RegisterRequest r,Role role){ if(usuarios.existsByEmail(r.email())) throw new IllegalArgumentException("E-mail já cadastrado"); Usuario u=new Usuario(); u.setNome(r.nome());u.setEmail(r.email());u.setSenha(encoder.encode(r.senha()));u.setTelefone(r.telefone());u.setRole(role); usuarios.save(u); Long empresaId=null; if(role==Role.EMPRESA){Empresa e=new Empresa(); e.setUsuario(u); e.setNomeFantasia(r.nomeFantasia()!=null&&!r.nomeFantasia().isBlank()?r.nomeFantasia():r.nome()); e.setDescricao("Estética automotiva cadastrada na plataforma Marques AutoDetail."); e.setTelefone(r.telefone()); e.setLatitude(-23.5505); e.setLongitude(-46.6333); Endereco end=new Endereco(); end.setCidade("São Paulo"); end.setEstado("SP"); end.setBairro("Centro"); end.setRua("Endereço a configurar"); e.setEndereco(end); empresas.save(e); empresaId=e.getId(); } return new AuthResponse(jwt.gerarToken(u),u.getId(),u.getNome(),u.getEmail(),u.getRole().name(),empresaId); }
 public AuthResponse login(LoginRequest r){ authManager.authenticate(new UsernamePasswordAuthenticationToken(r.email(),r.senha())); Usuario u=usuarios.findByEmail(r.email()).orElseThrow(); Long empresaId=empresas.findByUsuario(u).map(Empresa::getId).orElse(null); return new AuthResponse(jwt.gerarToken(u),u.getId(),u.getNome(),u.getEmail(),u.getRole().name(),empresaId); }
}
